function a(e,t){return`<OneUIBrandProvider brand="${e}" theme="${t}">`}function n(e){return['> Refined hierarchy for TSX generation. `kind:"component"` = a registered OneUI component (carries `component`, `props`, `appearance`, `surface`, `text`, `box`, `layout`, `children`). `kind:"surface"` = a surface frame \u2192 `<Surface mode=\u2026>`. `kind:"node"` = structural wrapper \u2192 `<Container>` with the token layout. `base` = the root\'s resolved modes.',"> **Spacing is token-based:** `layout.gap` / `layout.padding*` are spacing-token KEYS (resolve via theme.spacing) \u2014 emit them on `<Container>`/`<Surface>` props, never as literal px. `layout` also carries `cornerRadius` + `absoluteBox` (use absoluteBox only for pinned/absolute cases). direction\u2192flexDirection, justify/align\u2192justify/alignItems. `box` (w/h + sizeH/sizeV) sizes images (fixed\u2192w/h, fill\u2192flex/aspectRatio). Children are already in render order.",`> Wrap the screen in \`${e}\`, then \`validate_oneui_code\`. (Tip: re-run with \`codegen=true\` to auto-generate the .native.tsx.)`]}function r(e,t){return["## Mode B follow-up prompt","","Use this prompt after the generated scaffold exists:","","```text",`Using the Mode A scaffold written at ${t}, the refined tree returned below, and the assets in assets/figma/,`,"continue authoring the React Native screen in place.","","Rules:",`- Keep the screen wrapped in ${e}.`,"- Treat Mode A as the starting scaffold: edit the generated file instead of rebuilding from scratch.","- Use only supported @oneui/ui-native component props. Do not add visual shims for missing component APIs.","- Pin fixed/persistent footers outside the ScrollView and keep horizontal rails sized by content.",'- Run validate_oneui_code(platform:"reactnative") after edits, then build and screenshot to compare against Figma.',"```"]}export{n as reactNativeAuthoringGuidance,r as reactNativeModeBFollowupGuidance,a as reactNativeProviderTag};
